using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities; using OrcaFacil.Domain.Enums; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Areas.Admin.Pages.Support;
[Authorize(Policy="SuperAdmin")] public sealed class IndexModel(OrcaFacilDbContext db):PageModel
{
 public IReadOnlyList<SupportTicket> Tickets{get;private set;}=[]; public int OpenCount{get;private set;} public int UrgentCount{get;private set;} public int WaitingCount{get;private set;} public string? Status{get;set;} public string? Priority{get;set;} public string? Category{get;set;} public string? Search{get;set;}
 public async Task OnGetAsync(string? status,string? priority,string? category,string? search,CancellationToken ct){Status=status;Priority=priority;Category=category;Search=search;var all=db.SupportTickets.AsNoTracking().Where(x=>!x.IsDeleted);OpenCount=await all.CountAsync(x=>x.Status!=SupportTicketStatus.Closed&&x.Status!=SupportTicketStatus.Resolved,ct);UrgentCount=await all.CountAsync(x=>x.Priority==SupportTicketPriority.Urgent,ct);WaitingCount=await all.CountAsync(x=>x.Status==SupportTicketStatus.WaitingForUser,ct);if(Enum.TryParse<SupportTicketStatus>(status,out var s))all=all.Where(x=>x.Status==s);if(Enum.TryParse<SupportTicketPriority>(priority,out var p))all=all.Where(x=>x.Priority==p);if(Enum.TryParse<SupportTicketCategory>(category,out var c))all=all.Where(x=>x.Category==c);if(!string.IsNullOrWhiteSpace(search))all=all.Where(x=>x.Subject.Contains(search)||x.Protocol.Contains(search)||x.CorrelationId==search);Tickets=await all.OrderByDescending(x=>x.Priority).ThenByDescending(x=>x.CreatedAt).Take(200).ToListAsync(ct);}
}
